test('review validation rejects spoofed photos, oversized files, invalid ratings and missing consent',async()=>{
 const input={name:'Buyer',city:'Chennai',rating:5,text:'Love this print on my wall.',consent:true};
 assert.doesNotThrow(()=>validateReview(input));
 for(const patch of [{name:''},{name:'x'.repeat(101)},{city:'x'.repeat(101)},{rating:6},{rating:1.5},{text:'short'},{text:'x'.repeat(1201)},{consent:false}])assert.throws(()=>validateReview({...input,...patch}));
 await assert.rejects(validateReviewPhoto(new window.File(['x'],'file.svg',{type:'image/svg+xml'})));
 await assert.rejects(validateReviewPhoto(new window.File(['x'],'file.jpg',{type:'image/jpeg'})));
 await assert.rejects(validateReviewPhoto(new window.File([new Uint8Array(5242881)],'big.png',{type:'image/png'})));
 const png=Buffer.from('iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mP8/x8AAwMCAO+aL1cAAAAASUVORK5CYII=','base64');
 await assert.doesNotReject(validateReviewPhoto(new window.File([png],'wall.png',{type:'image/png'})));
})

