function fakeAdminApi(){const data=structuredClone(adminSeedFixture);let catalog={posters:data.catalog.posters.slice(0,2),revision:4},orders=data.orders,reviews=data.reviews,settings=defaultSiteSettings();const calls=[];let fail='';return {calls,set fail(value){fail=value},api:{loadSettings:async()=>settings,saveSettings:async next=>{calls.push(["settings",next]);if(fail==="settings")throw new Error("Settings changed. Reload and retry.");settings={...normalizeSiteSettings(next),revision:next.revision+1};return settings},loadCatalog:async()=>catalog,saveCatalog:async next=>{calls.push(['catalog',next]);if(fail==='catalog')throw new Error('Catalog changed. Reload and retry.');catalog={posters:next.posters,revision:next.revision+1};return catalog},uploadImage:async()=>{throw new Error('Image upload failed.')},loadOrders:async()=>orders,updateOrder:async(id,patch)=>{calls.push(['order',id,patch]);if(fail==='order')throw new Error('Order update failed.');orders=orders.map(o=>o.id===id?{...o,...patch}:o)},loadReviews:async()=>reviews,approveReview:async id=>{calls.push(['approve',id]);if(fail==='review')throw new Error('Review approval failed.');reviews=reviews.map(r=>r.id===id?{...r,approved:true}:r)},removeReview:async id=>{reviews=reviews.filter(r=>r.id!==id)}}}}
