 const d=normalizeSiteSettings({secret:'never-publish',revision:2,featuredConfig:{posterId:''},content:{faq:[],copy:{heroTitle:'Custom wall',footerDescription:'250 GSM paper'}},contact:{whatsappNumber:'bad'},shop:{instagramUsername:'javascript:bad'}});assert.equal('secret' in d,false);assert.deepEqual(d.content.faq,[]);assert.equal(d.featuredConfig.posterId,'');assert.equal(d.content.copy.footerDescription,'300 GSM paper');assert.equal(d.contact.whatsappNumber,'917598647185');assert.ok(!d.shop.instagramUsername.includes(':'));
